struct OrderFacade {                          // coarse-grained use-case boundary
    let pricing: PricingService
    let inventory: InventoryService
    let repo: OrderRepository
    func placeOrder(_ req: PlaceOrderRequest) async throws -> OrderID {
        let quote = try pricing.quote(sku: req.sku, qty: req.qty)
        try inventory.reserve(sku: req.sku, qty: req.qty)
        return try await repo.insert(customer: req.customerID, quote: quote)
    }
}
